```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, max(duration)/1e6 max_ms FROM (SELECT 'abn' src, * FROM abnormal_traces UNION ALL SELECT 'norm' src, * FROM normal_traces) WHERE (service_name='search' AND attr_span_kind='Client' AND span_name='rate.Rate/GetRates') OR (service_name='rate' AND attr_span_kind='Server') GROUP BY ALL ORDER BY span_name, service_name, src",
          "claim": "search's client spans to rate.Rate/GetRates rise from p50 0.47ms to about 1523ms, while rate's server spans stay near 0.8ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT src, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms FROM (SELECT 'abn' src, * FROM abnormal_traces UNION ALL SELECT 'norm' src, * FROM normal_traces) WHERE service_name='search' AND attr_span_kind='Client' AND span_name='geo.Geo/Nearby' GROUP BY ALL ORDER BY src",
          "claim": "search's client calls to geo from the same pod stay at about 0.5ms in both periods, so only the rate path is slowed."
        },
        {
          "kind": "metric",
          "sql": "SELECT src, metric, service_name, attr_k8s_pod_name pod, count(*) n, avg(value) avg_v FROM (SELECT 'abn' src, * FROM abnormal_metrics_sum UNION ALL SELECT 'norm', * FROM normal_metrics_sum) WHERE metric IN ('k8s.pod.network.errors','k8s.pod.network.io') AND service_name IN ('search','rate') GROUP BY ALL ORDER BY metric, pod, src",
          "claim": "Network I/O and error counters on the search and rate pods are unchanged between normal and abnormal periods, so the delay is not on the wire."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, quantile_cont(duration,0.95)/1e6 p95_ms, count(*) n FROM abnormal_traces WHERE (service_name='frontend' AND span_name='HTTP /hotels' AND attr_span_kind='Server') OR (service_name='search' AND attr_span_kind='Server') GROUP BY ALL ORDER BY service_name, span_name",
          "claim": "Frontend's /hotels server p95 is about 2907ms, matching search.Search/Nearby server p95 about 2906ms; frontend's own time stays small."
        }
      ]
    },
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT trace_id, service_name, span_name, attr_span_kind, duration/1000000.0 ms FROM abnormal_traces WHERE trace_id = 'a043122baac8198bb1231cbf305cf06e' ORDER BY time",
          "claim": "In one slow trace, rate's server span takes 0.14ms while search's client span to rate lasts 2194ms; the delay sits before rate."
        }
      ]
    }
  ]
}
```

